import 'package:app_bachhoa/services/admin_stats_service.dart';
import 'package:flutter/material.dart';

class ThongKeQuanLyPage extends StatefulWidget { const ThongKeQuanLyPage({super.key}); @override State<ThongKeQuanLyPage> createState()=>_ThongKeQuanLyPageState(); }
class _ThongKeQuanLyPageState extends State<ThongKeQuanLyPage>{ final _service=AdminStatsService(); AdminDashboardStats? _stats; bool _loading=true; @override void initState(){super.initState();_load();} Future<void> _load()async{setState(()=>_loading=true); final data=await _service.getDashboardStats(); if(!mounted)return; setState(() { _stats = data; _loading = false; });} String _money(double v){final s=v.toInt().toString(); final b=StringBuffer(); for(var i=0;i<s.length;i++){if(i>0&&(s.length-i)%3==0)b.write('.'); b.write(s[i]);} return '$b VND';} @override Widget build(BuildContext context){final s=_stats; return Scaffold(appBar:AppBar(title:const Text('Thống kê cửa hàng')),body:_loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:[_card('Doanh thu hôm nay',_money(s!.todayRevenue),Icons.payments,Colors.green),_card('Doanh thu tháng này',_money(s.monthRevenue),Icons.attach_money,Colors.purple),_card('Đơn hàng hôm nay',s.todayOrders.toString(),Icons.shopping_cart,Colors.orange),_card('Đơn chờ xác nhận',s.pendingOrders.toString(),Icons.pending_actions,Colors.indigo),_card('Sản phẩm sắp hết hàng',s.lowStockProducts.toString(),Icons.warning_amber,Colors.red),_card('Tổng sản phẩm',s.totalProducts.toString(),Icons.inventory_2,Colors.blue)])));} Widget _card(String title,String value,IconData icon,Color color)=>Card(child:ListTile(leading:CircleAvatar(backgroundColor:color.withValues(alpha:.12),child:Icon(icon,color:color)),title:Text(title),subtitle:Text(value,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold))));}

